#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float threshold;     // 0..1 bright-pass
    float glow_radius;   // 1..12 px
    float glow_strength; // 0..2
    float hue_shift;     // -1..1 (cycles neon hue)
    float edge_strength; // 0..2
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float3 rgb2hsv(float3 c){
    float4 K = float4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
    float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return float3(abs(q.z + (q.w - q.y) / (6.0*d + e)), d/(q.x+e), q.x);
}
static inline float3 hsv2rgb(float3 c){
    float4 K = float4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
    float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 texel = 1.0 / u.OutputSize.xy;
    float4 c = src.sample(s, in.uv);

    // Edge detection
    float3 kx[3] = {float3(-1,0,1), float3(-2,0,2), float3(-1,0,1)};
    float3 ky[3] = {float3(-1,-2,-1), float3(0,0,0), float3(1,2,1)};
    float gx = 0.0, gy = 0.0;
    for (int j=0;j<3;++j){
        for (int i=0;i<3;++i){
            float3 s3 = src.sample(s, in.uv + float2(i-1,j-1)*texel).rgb;
            float L = dot(s3, float3(0.2126,0.7152,0.0722));
            gx += L * kx[j][i];
            gy += L * ky[j][i];
        }
    }
    float edge = clamp(length(float2(gx,gy))*0.5, 0.0, 1.0);

    // Bright pass
    float lum = dot(c.rgb, float3(0.2126,0.7152,0.0722));
    float seed = max(0.0, lum - u.threshold);

    // Glow via small gaussian kernel (CPU-friendly radius)
    int r = int(clamp(u.glow_radius, 1.0, 12.0));
    float3 acc = float3(0.0); float wsum = 0.0;
    for (int y=-r;y<=r;++y){
        for (int x=-r;x<=r;++x){
            float2 o = float2(x,y);
            float w = exp(-dot(o,o) * (1.0/ max(1.0, float(r))));
            float3 s3 = src.sample(s, in.uv + o*texel).rgb;
            float L = dot(s3, float3(0.2126,0.7152,0.0722));
            float bp = max(0.0, L - u.threshold);
            acc += s3 * (bp * w);
            wsum += (bp * w);
        }
    }
    float3 glow = (wsum>0.0)? acc / wsum : c.rgb;

    // Neon colorize: hue shift on glow
    float3 hsv = rgb2hsv(glow);
    hsv.x = fract(hsv.x + u.hue_shift);
    float3 neon = hsv2rgb(hsv);

    float3 result = c.rgb;
    result += neon * u.glow_strength;
    result += edge * u.edge_strength * neon;

    return float4(saturate(result), c.a);
}

